import React, { useState, useEffect } from 'react';
import { Container, Row, Col, Card, Table, Badge, Button, Modal, Form, Alert } from 'react-bootstrap';
import { Link } from 'react-router-dom';
import { toast } from 'react-toastify';
import { bpmnAPI, adminAPI } from '../../services/api';
import { getUser } from '../../utils/auth';

const AdminDashboard = () => {
  const [stats, setStats] = useState({
    total: 0,
    pending: 0,
    approved: 0,
    rejected: 0,
    zoomAvailable: 0
  });
  const [recentRequests, setRecentRequests] = useState([]);
  const [zoomLinks, setZoomLinks] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showApproveModal, setShowApproveModal] = useState(false);
  const [showRejectModal, setShowRejectModal] = useState(false);
  const [showDetailModal, setShowDetailModal] = useState(false);
  const [selectedRequest, setSelectedRequest] = useState(null);
  const [selectedZoomId, setSelectedZoomId] = useState('');
  const [rejectionReason, setRejectionReason] = useState('');
  const [adminNotes, setAdminNotes] = useState('');
  
  // Manual Zoom Information Fields
  const [manualZoomLink, setManualZoomLink] = useState('');
  const [manualZoomMeetingId, setManualZoomMeetingId] = useState('');
  const [manualZoomPasscode, setManualZoomPasscode] = useState('');
  
  const user = getUser();

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    try {
      setLoading(true);
      
      // Coba menggunakan BPMN API terlebih dahulu
      try {
        const dashboardRes = await bpmnAPI.getAdminItDashboard();
        const zoomRes = await adminAPI.getZoomLinks();
        
        const { stats: dashboardStats, recentRequests: recentReq } = dashboardRes.data;
        const zooms = zoomRes.data;
        
        setStats({
          total: dashboardStats.total_requests || 0,
          pending: dashboardStats.pending_requests || 0,
          approved: dashboardStats.validated_requests || 0,
          rejected: dashboardStats.rejected_requests || 0,
          zoomAvailable: zooms.filter(z => z.is_active).length
        });
        
        // Filter requests untuk Admin IT - hanya zoom dan both
        const adminRelevantRequests = (recentReq || []).filter(request => 
          request.request_type === 'zoom' || request.request_type === 'both'
        );
        
        setRecentRequests(adminRelevantRequests);
        setZoomLinks(zooms);
        
      } catch (bpmnError) {
        console.log('BPMN API not ready, using fallback...');
        
        // Fallback ke API lama dengan error handling
        try {
          const [requestsRes, zoomRes] = await Promise.all([
            adminAPI.getAllRequests(),
            adminAPI.getZoomLinks()
          ]);

          console.log('📋 Requests response:', requestsRes);
          console.log('🔗 Zoom response:', zoomRes);

          // Handle requests data with validation
          let requests = [];
          if (requestsRes.data) {
            if (Array.isArray(requestsRes.data)) {
              requests = requestsRes.data;
            } else if (requestsRes.data.data && Array.isArray(requestsRes.data.data)) {
              requests = requestsRes.data.data;
            }
          }

          // Handle zoom links data with validation
          let zooms = [];
          if (zoomRes.data) {
            if (Array.isArray(zoomRes.data)) {
              zooms = zoomRes.data;
            } else if (zoomRes.data.data && Array.isArray(zoomRes.data.data)) {
              zooms = zoomRes.data.data;
            }
          }

          // Ensure both are arrays
          if (!Array.isArray(requests)) {
            console.warn('⚠️ Requests is not an array, setting to empty array');
            requests = [];
          }

          if (!Array.isArray(zooms)) {
            console.warn('⚠️ Zooms is not an array, setting to empty array');
            zooms = [];
          }

          console.log('📊 Processed requests:', requests);
          console.log('🔗 Processed zooms:', zooms);

          // Calculate stats
          const stats = {
            total: requests.length,
            pending: requests.filter(r => r.status === 'pending').length,
            approved: requests.filter(r => r.status === 'approved').length,
            rejected: requests.filter(r => r.status === 'rejected').length,
            zoomAvailable: zooms.filter(z => z.is_active).length
          };

          setStats(stats);
          
          // Filter requests untuk Admin IT - hanya zoom dan both
          const adminRelevantRequests = requests.filter(request => 
            request.request_type === 'zoom' || request.request_type === 'both'
          );
          
          setRecentRequests(adminRelevantRequests.slice(0, 5));
          setZoomLinks(zooms);
          
        } catch (fallbackError) {
          console.error('❌ Fallback also failed:', fallbackError);
          
          // Set empty data on complete failure
          setStats({
            total: 0,
            pending: 0,
            approved: 0,
            rejected: 0,
            zoomAvailable: 0
          });
          setRecentRequests([]);
          setZoomLinks([]);
          
          toast.error('Gagal memuat data dashboard');
        }
      }
      
    } catch (error) {
      console.error('Error fetching admin dashboard data:', error);
      toast.error('Gagal memuat data dashboard');
    } finally {
      setLoading(false);
    }
  };

  const handleApprove = (request) => {
    setSelectedRequest(request);
    setAdminNotes('');
    if (request.request_type === 'zoom' || request.request_type === 'both') {
      setShowApproveModal(true);
    } else {
      // Direct approve for room only
      submitApprove(request.id, null);
    }
  };

  const handleReject = (request) => {
    setSelectedRequest(request);
    setShowRejectModal(true);
  };

  const handleDetail = (request) => {
    setSelectedRequest(request);
    setShowDetailModal(true);
  };

  const submitApprove = async (requestId, zoomLinkId) => {
    try {
      // Coba menggunakan BPMN API terlebih dahulu
      try {
        const data = {
          action: 'approve'
        };
        if (zoomLinkId) {
          data.zoom_link_id = zoomLinkId;
        }
        
        // Tambahkan admin notes jika ada
        if (adminNotes.trim()) {
          data.admin_notes = adminNotes.trim();
        }
        
        // Tambahkan manual Zoom information jika ada
        if (manualZoomLink.trim() || manualZoomMeetingId.trim() || manualZoomPasscode.trim()) {
          data.zoom_link_manual = manualZoomLink.trim() || null;
          data.zoom_meeting_id_manual = manualZoomMeetingId.trim() || null;
          data.zoom_passcode_manual = manualZoomPasscode.trim() || null;
        }
        
        await bpmnAPI.adminItValidateRequest(requestId, data);
        
        // Berikan pesan yang spesifik berdasarkan jenis request
        if (selectedRequest.request_type === 'zoom') {
          toast.success('✅ Zoom request berhasil disetujui dan diselesaikan!');
        } else if (selectedRequest.request_type === 'both') {
          toast.success('✅ Zoom disetujui, request diteruskan ke Logistik untuk approval ruangan!');
        } else {
          toast.success('✅ Request divalidasi dan diteruskan ke Logistik!');
        }
        
      } catch (bpmnError) {
        console.log('BPMN API not ready, using fallback...');
        // Fallback ke API lama
        const data = zoomLinkId ? { 
          zoom_link_id: zoomLinkId,
          admin_notes: adminNotes.trim() || undefined
        } : {
          admin_notes: adminNotes.trim() || undefined
        };
        
        // Tambahkan manual Zoom information untuk fallback juga
        if (manualZoomLink.trim() || manualZoomMeetingId.trim() || manualZoomPasscode.trim()) {
          data.zoom_link_manual = manualZoomLink.trim() || null;
          data.zoom_meeting_id_manual = manualZoomMeetingId.trim() || null;
          data.zoom_passcode_manual = manualZoomPasscode.trim() || null;
        }
        
        await adminAPI.approveRequest(requestId, data);
        toast.success('Request berhasil disetujui!');
      }
      
      fetchDashboardData();
      setShowApproveModal(false);
      setSelectedZoomId('');
      setAdminNotes('');
      // Reset manual Zoom fields
      setManualZoomLink('');
      setManualZoomMeetingId('');
      setManualZoomPasscode('');
    } catch (error) {
      console.error('Error approving request:', error);
      toast.error('Gagal menyetujui request');
    }
  };

  const submitReject = async () => {
    if (!rejectionReason.trim()) {
      toast.error('Alasan penolakan harus diisi');
      return;
    }

    try {
      // Coba menggunakan BPMN API terlebih dahulu
      try {
        await bpmnAPI.adminItValidateRequest(selectedRequest.id, {
          action: 'reject',
          reason: rejectionReason
        });
        toast.success('Request berhasil ditolak!');
        
      } catch (bpmnError) {
        console.log('BPMN API not ready, using fallback...');
        // Fallback ke API lama
        await adminAPI.rejectRequest(selectedRequest.id, {
          rejection_reason: rejectionReason
        });
        toast.success('Request berhasil ditolak!');
      }
      
      fetchDashboardData();
      setShowRejectModal(false);
      setRejectionReason('');
    } catch (error) {
      console.error('Error rejecting request:', error);
      toast.error('Gagal menolak request');
    }
  };

  const getStatusBadge = (status) => {
    const variants = {
      pending: 'warning',
      approved: 'success',
      rejected: 'danger'
    };
    return <Badge bg={variants[status]}>{status.toUpperCase()}</Badge>;
  };

  const getTypeBadge = (type) => {
    const variants = {
      room: 'info',
      zoom: 'primary',
      both: 'success'
    };
    const labels = {
      room: 'Ruangan',
      zoom: 'Zoom',
      both: 'Ruangan + Zoom'
    };
    return <Badge bg={variants[type]}>{labels[type]}</Badge>;
  };

  if (loading) {
    return (
      <div className="d-flex justify-content-center align-items-center" style={{ minHeight: '60vh' }}>
        <div className="text-center">
          <div className="spinner-border text-primary mb-3" style={{ width: '3rem', height: '3rem' }}>
            <span className="visually-hidden">Loading...</span>
          </div>
          <p className="text-muted">Memuat dashboard admin IT...</p>
        </div>
      </div>
    );
  }

  return (
    <Container fluid className="py-4">
      {/* Header */}
      <Row className="mb-5">
        <Col>
          <div className="fade-in-up">
            <div className="d-flex align-items-center mb-3">
              <div className="bg-gradient-primary rounded-circle d-flex align-items-center justify-content-center me-3" style={{ width: '60px', height: '60px' }}>
                <i className="fas fa-user-shield text-white fs-4"></i>
              </div>
              <div>
                <h1 className="text-gradient mb-1">Dashboard Admin IT</h1>
                <p className="text-muted mb-0 fs-5">
                  <i className="fas fa-video me-2 text-primary"></i>
                  Selamat datang, {user?.name || user?.email}!
                </p>
              </div>
            </div>
          </div>
        </Col>
        <Col xs="auto" className="d-flex align-items-start">
          <div className="fade-in-right d-flex gap-2">
            <Button as={Link} to="/admin/zoom" variant="primary" size="lg" className="shadow-soft">
              <i className="fas fa-video me-2"></i>
              Kelola Zoom
            </Button>
            <Button as={Link} to="/admin/bookings" variant="outline-primary" size="lg" className="shadow-soft">
              <i className="fas fa-list me-2"></i>
              Semua Booking
            </Button>
          </div>
        </Col>
      </Row>

      {/* Role Information */}
      <Row className="mb-5">
        <Col>
          <Alert variant="primary" className="fade-in-up border-0 shadow-soft" style={{ animationDelay: '0.1s' }}>
            <Alert.Heading className="h5 mb-3">
              <i className="fas fa-info-circle me-2"></i>
              Role Admin IT
            </Alert.Heading>
            <p className="mb-2">
              <i className="fas fa-check me-2 text-success"></i>
              Anda bertanggung jawab untuk memvalidasi request dan mengelola zoom.
            </p>
            <p className="mb-2">
              <i className="fas fa-video me-2 text-info"></i>
              Request <strong>zoom-only</strong> akan langsung diselesaikan oleh Anda.
            </p>
            <p className="mb-0">
              <i className="fas fa-arrow-right me-2 text-warning"></i>
              Request yang membutuhkan <strong>ruangan</strong> akan diteruskan ke Logistik setelah validasi.
            </p>
          </Alert>
        </Col>
      </Row>

      {/* Stats Cards */}
      <Row className="mb-5 g-4">
        <Col md={6} lg={2}>
          <Card className="stats-card bg-primary text-white fade-in-up" style={{ animationDelay: '0.1s' }}>
            <Card.Body className="text-center">
              <i className="fas fa-calendar-alt fa-3x mb-3"></i>
              <h2 className="fw-bold">{stats.total}</h2>
              <p className="mb-0 opacity-90">Total Request</p>
            </Card.Body>
          </Card>
        </Col>
        <Col md={6} lg={2}>
          <Card className="stats-card bg-warning text-white fade-in-up" style={{ animationDelay: '0.2s' }}>
            <Card.Body className="text-center">
              <i className="fas fa-clock fa-3x mb-3"></i>
              <h2 className="fw-bold">{stats.pending}</h2>
              <p className="mb-0 opacity-90">Pending</p>
            </Card.Body>
          </Card>
        </Col>
        <Col md={6} lg={2}>
          <Card className="stats-card bg-success text-white fade-in-up" style={{ animationDelay: '0.3s' }}>
            <Card.Body className="text-center">
              <i className="fas fa-check-circle fa-3x mb-3"></i>
              <h2 className="fw-bold">{stats.approved}</h2>
              <p className="mb-0 opacity-90">Approved</p>
            </Card.Body>
          </Card>
        </Col>
        <Col md={6} lg={2}>
          <Card className="stats-card bg-danger text-white fade-in-up" style={{ animationDelay: '0.4s' }}>
            <Card.Body className="text-center">
              <i className="fas fa-times-circle fa-3x mb-3"></i>
              <h2 className="fw-bold">{stats.rejected}</h2>
              <p className="mb-0 opacity-90">Rejected</p>
            </Card.Body>
          </Card>
        </Col>
        <Col md={6} lg={2}>
          <Card className="stats-card bg-info text-white fade-in-up" style={{ animationDelay: '0.5s' }}>
            <Card.Body className="text-center">
              <i className="fas fa-video fa-3x mb-3"></i>
              <h2 className="fw-bold">{stats.zoomAvailable}</h2>
              <p className="mb-0 opacity-90">Zoom Tersedia</p>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* Recent Requests */}
      <Row>
        <Col>
          <Card className="fade-in-up" style={{ animationDelay: '0.6s' }}>
            <Card.Header className="d-flex justify-content-between align-items-center">
              <div className="d-flex align-items-center">
                <i className="fas fa-history me-2 text-primary"></i>
                <h4 className="mb-0 fw-bold">Request Terbaru</h4>
              </div>
              <Badge bg="primary" pill className="fs-6">{recentRequests.length} Request</Badge>
            </Card.Header>
            <Card.Body className="p-0">
              {recentRequests.length > 0 ? (
                <div className="table-responsive">
                  <Table className="mb-0" hover>
                    <thead>
                      <tr>
                        <th className="border-0 fw-bold">User & Request</th>
                        <th className="border-0 fw-bold">Tanggal & Waktu</th>
                        <th className="border-0 fw-bold">Jenis & Detail</th>
                        <th className="border-0 fw-bold">Zoom Info</th>
                        <th className="border-0 fw-bold">Status</th>
                        <th className="border-0 fw-bold">Aksi</th>
                      </tr>
                    </thead>
                    <tbody>
                      {recentRequests.map((request, index) => (
                        <tr key={request.id} className="fade-in-up" style={{ animationDelay: `${0.7 + index * 0.05}s` }}>
                          <td>
                            <div>
                              <div className="fw-bold text-dark">{request.user_name || request.user_email}</div>
                              <small className="text-muted">{request.user_email}</small>
                              <div className="mt-1">
                                <div className="fw-medium text-primary">{request.title}</div>
                                <small className="text-muted">{request.purpose}</small>
                              </div>
                            </div>
                          </td>
                          <td>
                            <div>
                              <div className="fw-medium">
                                <i className="fas fa-calendar me-1 text-primary"></i>
                                {new Date(request.date).toLocaleDateString('id-ID', {
                                  weekday: 'short',
                                  year: 'numeric',
                                  month: 'short',
                                  day: 'numeric'
                                })}
                              </div>
                              <small className="text-muted">
                                <i className="fas fa-clock me-1"></i>
                                {request.start_time} - {request.end_time}
                              </small>
                              <div className="mt-1">
                                <small className="text-muted">
                                  <i className="fas fa-plus me-1"></i>
                                  {new Date(request.created_at).toLocaleDateString('id-ID')}
                                </small>
                              </div>
                            </div>
                          </td>
                          <td>
                            <div className="d-flex flex-column gap-1">
                              {getTypeBadge(request.request_type)}
                              <small className="text-muted">
                                <i className="fas fa-users me-1"></i>
                                {request.participants || 'N/A'} peserta
                              </small>
                            </div>
                          </td>
                          <td>
                            {request.zoom_link ? (
                              <div>
                                <Badge bg="success" className="mb-1">Zoom Assigned</Badge>
                                <br />
                                <small className="text-success">
                                  <i className="fas fa-check-circle me-1"></i>
                                  Link tersedia
                                </small>
                              </div>
                            ) : (
                              <div>
                                <Badge bg="secondary">Belum Ada Zoom</Badge>
                                <br />
                                <small className="text-muted">
                                  <i className="fas fa-clock me-1"></i>
                                  Menunggu assign
                                </small>
                              </div>
                            )}
                          </td>
                          <td>{getStatusBadge(request.status)}</td>
                          <td>
                            <div className="d-flex gap-1 flex-wrap">
                              {/* Detail Button */}
                              <Button
                                variant="info"
                                size="sm"
                                onClick={() => handleDetail(request)}
                                title="Lihat Detail"
                                className="d-flex align-items-center"
                              >
                                <i className="fas fa-eye me-1"></i>
                                <span className="d-none d-md-inline">Detail</span>
                              </Button>

                              {request.status === 'pending' && (
                                <>
                                  {/* Admin IT hanya bisa handle zoom dan both (untuk bagian zoom) */}
                                  {(request.request_type === 'zoom' || request.request_type === 'both') && (
                                    <>
                                      <Button
                                        variant="success"
                                        size="sm"
                                        onClick={() => handleApprove(request)}
                                        title="Approve Zoom"
                                        className="d-flex align-items-center"
                                      >
                                        <i className="fas fa-check me-1"></i>
                                        <span className="d-none d-lg-inline">Approve</span>
                                      </Button>
                                      <Button
                                        variant="danger"
                                        size="sm"
                                        onClick={() => handleReject(request)}
                                        title="Reject Request"
                                        className="d-flex align-items-center"
                                      >
                                        <i className="fas fa-times me-1"></i>
                                        <span className="d-none d-lg-inline">Reject</span>
                                      </Button>
                                    </>
                                  )}
                                  {/* Untuk request room-only, admin tidak bisa approve */}
                                  {request.request_type === 'room' && (
                                    <Badge bg="secondary" className="d-flex align-items-center">
                                      <i className="fas fa-info-circle me-1"></i>
                                      Logistik Only
                                    </Badge>
                                  )}
                                </>
                              )}
                            </div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </Table>
                </div>
              ) : (
                <div className="text-center py-5">
                  <div className="mb-4">
                    <i className="fas fa-inbox text-muted" style={{ fontSize: '4rem' }}></i>
                  </div>
                  <h5 className="text-muted mb-3">Tidak Ada Request Terbaru</h5>
                  <p className="text-muted mb-4">
                    Request baru akan muncul di sini ketika user mengajukan permintaan meeting.
                  </p>
                  <Button as={Link} to="/admin/zoom" variant="primary" size="lg" className="px-4">
                    <i className="fas fa-video me-2"></i>
                    Kelola Zoom
                  </Button>
                </div>
              )}
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* Approve Modal */}
      <Modal show={showApproveModal} onHide={() => setShowApproveModal(false)} size="lg">
        <Modal.Header closeButton>
          <Modal.Title>
            <i className="fas fa-check-circle me-2 text-success"></i>
            {selectedRequest?.request_type === 'zoom' ? 'Approve Zoom Request' :
             selectedRequest?.request_type === 'both' ? 'Validate Request & Approve Zoom' :
             'Validate Request'}
          </Modal.Title>
        </Modal.Header>
        <Modal.Body>
          {selectedRequest && (
            <>
              <Alert variant="success">
                <Alert.Heading className="h6 mb-2">
                  <i className="fas fa-user-shield me-2"></i>
                  Admin IT Role
                </Alert.Heading>
                {selectedRequest.request_type === 'zoom' && 
                  <p className="mb-0">Anda akan meng-approve zoom dan menyelesaikan request.</p>
                }
                {selectedRequest.request_type === 'both' && 
                  <p className="mb-0">Anda akan meng-approve zoom dan meneruskan ke logistik untuk approval ruangan.</p>
                }
                {selectedRequest.request_type === 'room' && 
                  <p className="mb-0">Request ini hanya untuk ruangan, akan langsung diteruskan ke logistik.</p>
                }
              </Alert>
              
              <div className="mb-4">
                <h6 className="text-primary mb-3">
                  <i className="fas fa-info-circle me-2"></i>
                  Detail Request
                </h6>
                <Row>
                  <Col md={6}>
                    <p className="mb-2"><strong>Judul:</strong> {selectedRequest.title}</p>
                    <p className="mb-2"><strong>User:</strong> {selectedRequest.user_email}</p>
                  </Col>
                  <Col md={6}>
                    <p className="mb-2"><strong>Tanggal:</strong> {new Date(selectedRequest.date).toLocaleDateString('id-ID')}</p>
                    <p className="mb-2"><strong>Waktu:</strong> {selectedRequest.start_time} - {selectedRequest.end_time}</p>
                  </Col>
                </Row>
                <p className="mb-0">
                  <strong>Jenis:</strong> 
                  {selectedRequest.request_type === 'zoom' && <Badge bg="primary" className="ms-2">Zoom Only</Badge>}
                  {selectedRequest.request_type === 'room' && <Badge bg="success" className="ms-2">Room Only</Badge>}
                  {selectedRequest.request_type === 'both' && <Badge bg="warning" className="ms-2">Zoom + Room</Badge>}
                </p>
              </div>

              {(selectedRequest.request_type === 'zoom' || selectedRequest.request_type === 'both') && (
                <>
                  <Form.Group className="mb-4">
                    <Form.Label className="fw-bold">
                      <i className="fas fa-video me-2 text-primary"></i>
                      Pilih Zoom Account: <span className="text-danger">*</span>
                    </Form.Label>
                    <Form.Select
                      value={selectedZoomId}
                      onChange={(e) => setSelectedZoomId(e.target.value)}
                      required
                    >
                      <option value="">-- Pilih Zoom Account --</option>
                      {zoomLinks.filter(z => z.is_active).map(zoom => (
                        <option key={zoom.id} value={zoom.id}>
                          {zoom.zoom_account_name} ({zoom.zoom_email})
                        </option>
                      ))}
                    </Form.Select>
                  </Form.Group>

                  {/* Manual Zoom Information Section */}
                  <div className="mb-4">
                    <h6 className="text-primary">
                      <i className="fas fa-edit me-2"></i>
                      Informasi Zoom Manual (Opsional)
                    </h6>
                    <Alert variant="info" className="small">
                      <i className="fas fa-info-circle me-2"></i>
                      Isi informasi Zoom yang akan diberikan kepada user (akan menggantikan informasi dari akun Zoom)
                    </Alert>
                    
                    <Form.Group className="mb-3">
                      <Form.Label>Zoom Link:</Form.Label>
                      <Form.Control
                        type="url"
                        value={manualZoomLink}
                        onChange={(e) => setManualZoomLink(e.target.value)}
                        placeholder="https://zoom.us/j/123456789?pwd=password123"
                      />
                    </Form.Group>

                    <Row>
                      <Col md={6}>
                        <Form.Group className="mb-3">
                          <Form.Label>Meeting ID:</Form.Label>
                          <Form.Control
                            type="text"
                            value={manualZoomMeetingId}
                            onChange={(e) => setManualZoomMeetingId(e.target.value)}
                            placeholder="123 456 7890"
                          />
                        </Form.Group>
                      </Col>
                      <Col md={6}>
                        <Form.Group className="mb-3">
                          <Form.Label>Passcode:</Form.Label>
                          <Form.Control
                            type="text"
                            value={manualZoomPasscode}
                            onChange={(e) => setManualZoomPasscode(e.target.value)}
                            placeholder="password123"
                          />
                        </Form.Group>
                      </Col>
                    </Row>
                  </div>
                </>
              )}

              {/* Admin Notes Section */}
              <Form.Group className="mb-3">
                <Form.Label className="fw-bold">
                  <i className="fas fa-sticky-note me-2 text-warning"></i>
                  Catatan untuk User (Opsional):
                </Form.Label>
                <Form.Control
                  as="textarea"
                  rows={3}
                  value={adminNotes}
                  onChange={(e) => setAdminNotes(e.target.value)}
                  placeholder="Berikan catatan tambahan untuk user (opsional)..."
                />
                <Form.Text className="text-muted">
                  Catatan ini akan dilihat oleh user di detail booking mereka.
                </Form.Text>
              </Form.Group>
            </>
          )}
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowApproveModal(false)}>
            Batal
          </Button>
          <Button 
            variant="success" 
            onClick={() => submitApprove(selectedRequest?.id, selectedZoomId || null)}
            disabled={
              (selectedRequest?.request_type === 'zoom' || selectedRequest?.request_type === 'both') 
              && !selectedZoomId
            }
          >
            {selectedRequest?.request_type === 'zoom' ? 'Approve Zoom' :
             selectedRequest?.request_type === 'both' ? 'Validate & Approve Zoom' :
             'Validate Request'}
          </Button>
        </Modal.Footer>
      </Modal>

      {/* Detail Modal */}
      <Modal show={showDetailModal} onHide={() => setShowDetailModal(false)} size="lg">
        <Modal.Header closeButton>
          <Modal.Title>Detail Booking</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          {selectedRequest && (
            <div>
              <Row className="mb-3">
                <Col md={6}>
                  <strong>Judul Acara:</strong>
                  <p>{selectedRequest.title}</p>
                </Col>
                <Col md={6}>
                  <strong>Penyelenggara:</strong>
                  <p>{selectedRequest.user_email}</p>
                </Col>
              </Row>

              <Row className="mb-3">
                <Col md={6}>
                  <strong>Tanggal:</strong>
                  <p>{new Date(selectedRequest.date).toLocaleDateString('id-ID')}</p>
                </Col>
                <Col md={6}>
                  <strong>Waktu:</strong>
                  <p>{selectedRequest.start_time} - {selectedRequest.end_time}</p>
                </Col>
              </Row>

              <Row className="mb-3">
                <Col md={6}>
                  <strong>Jenis Request:</strong>
                  <p>
                    <Badge bg={
                      selectedRequest.request_type === 'room' ? 'primary' :
                      selectedRequest.request_type === 'zoom' ? 'success' : 'info'
                    }>
                      {selectedRequest.request_type === 'room' ? 'Ruangan Saja' :
                       selectedRequest.request_type === 'zoom' ? 'Zoom Saja' : 'Ruangan + Zoom'}
                    </Badge>
                  </p>
                </Col>
                <Col md={6}>
                  <strong>Status:</strong>
                  <p>
                    <Badge bg={
                      selectedRequest.status === 'approved' ? 'success' :
                      selectedRequest.status === 'rejected' ? 'danger' : 'warning'
                    }>
                      {selectedRequest.status === 'approved' ? 'Disetujui' :
                       selectedRequest.status === 'rejected' ? 'Ditolak' : 'Menunggu'}
                    </Badge>
                  </p>
                </Col>
              </Row>

              {selectedRequest.request_type !== 'zoom' && (
                <Row className="mb-3">
                  <Col md={6}>
                    <strong>Ruangan:</strong>
                    <p>{selectedRequest.room_name || 'Belum dialokasikan'}</p>
                  </Col>
                  <Col md={6}>
                    <strong>Jumlah Peserta:</strong>
                    <p>{selectedRequest.participant_count} orang</p>
                  </Col>
                </Row>
              )}

              <Row className="mb-3">
                <Col md={6}>
                  <strong>Kontak PIC:</strong>
                  <p>{selectedRequest.pic_contact || 'Tidak ada kontak PIC'}</p>
                </Col>
                <Col md={6}>
                  <strong>Dibuat:</strong>
                  <p>{new Date(selectedRequest.created_at).toLocaleString('id-ID')}</p>
                </Col>
              </Row>

              <Row className="mb-3">
                <Col md={12}>
                  <strong>Deskripsi:</strong>
                  <p>{selectedRequest.description || 'Tidak ada deskripsi'}</p>
                </Col>
              </Row>

              {/* Informasi Zoom */}
              {(selectedRequest.request_type === 'zoom' || selectedRequest.request_type === 'both') && (
                <div className="mt-4">
                  <h6>Informasi Zoom</h6>
                  <hr />
                  
                  {/* Manual Zoom Info */}
                  {selectedRequest.zoom_link_manual && (
                    <div className="bg-light p-3 rounded mb-3">
                      <div className="d-flex justify-content-between align-items-center mb-2">
                        <h6 className="mb-0">Informasi Zoom Manual</h6>
                        <Badge bg="success">Manual</Badge>
                      </div>
                      <Row>
                        <Col md={12} className="mb-2">
                          <strong>Link Meeting:</strong>
                          <p className="mb-1">
                            <a href={selectedRequest.zoom_link_manual} target="_blank" rel="noopener noreferrer">
                              {selectedRequest.zoom_link_manual}
                            </a>
                          </p>
                        </Col>
                        {selectedRequest.zoom_meeting_id_manual && (
                          <Col md={6} className="mb-2">
                            <strong>Meeting ID:</strong>
                            <p className="mb-1">{selectedRequest.zoom_meeting_id_manual}</p>
                          </Col>
                        )}
                        {selectedRequest.zoom_passcode_manual && (
                          <Col md={6} className="mb-2">
                            <strong>Passcode:</strong>
                            <p className="mb-1">{selectedRequest.zoom_passcode_manual}</p>
                          </Col>
                        )}
                      </Row>
                    </div>
                  )}
                  
                  {/* Auto Zoom Info */}
                  {selectedRequest.zoom_link && !selectedRequest.zoom_link_manual && (
                    <div className="bg-light p-3 rounded mb-3">
                      <div className="d-flex justify-content-between align-items-center mb-2">
                        <h6 className="mb-0">Informasi Zoom Otomatis</h6>
                        <Badge bg="info">Auto</Badge>
                      </div>
                      <Row>
                        <Col md={12} className="mb-2">
                          <strong>Link Meeting:</strong>
                          <p className="mb-1">
                            <a href={selectedRequest.zoom_link} target="_blank" rel="noopener noreferrer">
                              {selectedRequest.zoom_link}
                            </a>
                          </p>
                        </Col>
                        {selectedRequest.zoom_meeting_id && (
                          <Col md={6} className="mb-2">
                            <strong>Meeting ID:</strong>
                            <p className="mb-1">{selectedRequest.zoom_meeting_id}</p>
                          </Col>
                        )}
                        {selectedRequest.zoom_passcode && (
                          <Col md={6} className="mb-2">
                            <strong>Passcode:</strong>
                            <p className="mb-1">{selectedRequest.zoom_passcode}</p>
                          </Col>
                        )}
                      </Row>
                    </div>
                  )}

                  {/* No Zoom Info */}
                  {!selectedRequest.zoom_link && !selectedRequest.zoom_link_manual && (
                    <div className="text-muted">
                      <p>Informasi Zoom belum tersedia</p>
                    </div>
                  )}
                </div>
              )}

              {/* Admin Notes */}
              {selectedRequest.admin_notes && (
                <div className="mt-4">
                  <h6>Catatan Admin</h6>
                  <hr />
                  <div className="bg-light p-3 rounded">
                    <p className="mb-0">{selectedRequest.admin_notes}</p>
                  </div>
                </div>
              )}

              {/* Rejection Reason */}
              {selectedRequest.status === 'rejected' && selectedRequest.rejection_reason && (
                <div className="mt-4">
                  <h6>Alasan Penolakan</h6>
                  <hr />
                  <div className="bg-danger bg-opacity-10 p-3 rounded border border-danger border-opacity-25">
                    <p className="mb-0 text-danger">{selectedRequest.rejection_reason}</p>
                  </div>
                </div>
              )}
            </div>
          )}
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowDetailModal(false)}>
            Tutup
          </Button>
        </Modal.Footer>
      </Modal>

      {/* Reject Modal */}
      <Modal show={showRejectModal} onHide={() => setShowRejectModal(false)}>
        <Modal.Header closeButton>
          <Modal.Title>
            <i className="fas fa-times-circle me-2 text-danger"></i>
            Tolak Request
          </Modal.Title>
        </Modal.Header>
        <Modal.Body>
          {selectedRequest && (
            <>
              <Alert variant="danger">
                <i className="fas fa-exclamation-triangle me-2"></i>
                Anda akan menolak request dari <strong>{selectedRequest.user_email}</strong> untuk acara <strong>{selectedRequest.title}</strong>
              </Alert>
              
              <div className="mb-3">
                <h6 className="text-muted">Detail Request:</h6>
                <ul className="mb-0">
                  <li><strong>Tanggal:</strong> {new Date(selectedRequest.date).toLocaleDateString('id-ID')}</li>
                  <li><strong>Waktu:</strong> {selectedRequest.start_time} - {selectedRequest.end_time}</li>
                  <li><strong>Jenis:</strong> {getTypeBadge(selectedRequest.request_type)}</li>
                </ul>
              </div>

              <Form.Group className="mb-3">
                <Form.Label className="fw-bold">
                  <i className="fas fa-comment-slash me-2 text-danger"></i>
                  Alasan Penolakan: <span className="text-danger">*</span>
                </Form.Label>
                <Form.Control
                  as="textarea"
                  rows={3}
                  value={rejectionReason}
                  onChange={(e) => setRejectionReason(e.target.value)}
                  placeholder="Jelaskan alasan penolakan..."
                  required
                />
                <Form.Text className="text-muted">
                  Alasan ini akan dilihat oleh user di detail booking mereka.
                </Form.Text>
              </Form.Group>
            </>
          )}
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowRejectModal(false)}>
            Batal
          </Button>
          <Button 
            variant="danger" 
            onClick={submitReject}
            disabled={!rejectionReason.trim()}
          >
            <i className="fas fa-times me-2"></i>
            Tolak Request
          </Button>
        </Modal.Footer>
      </Modal>
    </Container>
  );
};

export default AdminDashboard;
